/** Cut xterm.js, its fit addon and its stylesheet into `src/xterm.gen.ts`, so
 *  the phone's terminal draws offline from inside the app bundle: the WebView
 *  it runs in loads a page built from a string, with nothing fetched.
 *
 *     npm pack @xterm/xterm@6.0.0 @xterm/addon-fit@0.11.0   (in an empty folder)
 *     node scripts/gen-xterm.cjs <xterm package dir> <addon-fit package dir>
 *
 *  Each directory is an unpacked package (the one holding `package.json`). Not
 *  a check, and in no npm script. */
const fs = require('fs');
const path = require('path');

const [xtermDir, fitDir] = process.argv.slice(2);
if (!xtermDir || !fitDir) {
  console.error('usage: node scripts/gen-xterm.cjs <xterm dir> <addon-fit dir>');
  process.exit(2);
}
const read = (dir, f) => fs.readFileSync(path.join(dir, f), 'utf8');
const version = (dir) => JSON.parse(read(dir, 'package.json')).version;
// The source map comment points at a file that is not shipped.
const strip = (s) => s.replace(/\n\/\/# sourceMappingURL=.*\s*$/, '\n');
const js = strip(read(xtermDir, 'lib/xterm.js'));
const fit = strip(read(fitDir, 'lib/addon-fit.js'));
const css = read(xtermDir, 'css/xterm.css');
for (const s of [js, fit, css]) {
  if (/<\/script|<\/style/i.test(s)) throw new Error('a closing tag inside the source would end the page early');
}
const lit = (s) => JSON.stringify(s).replace(/[\u2028\u2029]/g, (c) => `\\u${c.charCodeAt(0).toString(16)}`);

const out = `// Generated by scripts/gen-xterm.cjs - do not edit.
// xterm.js ${version(xtermDir)} and @xterm/addon-fit ${version(fitDir)} (MIT License,
// Copyright (c) 2017-2019 The xterm.js authors, 2014-2016 SourceLair Private
// Company, 2012-2013 Christopher Jeffrey), as the text of their UMD builds.
/* eslint-disable */
export const XTERM_VERSION = ${JSON.stringify(version(xtermDir))};
export const XTERM_JS: string = ${lit(js)};
export const XTERM_FIT_JS: string = ${lit(fit)};
export const XTERM_CSS: string = ${lit(css)};
`;
const dest = path.join(__dirname, '..', 'src', 'xterm.gen.ts');
fs.writeFileSync(dest, out);
console.log(`${dest}: ${out.length} bytes`);
